// Game languages (since 0.5.3): Italian, English, Spanish, Portuguese (from Portugal), Simplified
// Chinese, Japanese, Hindi.
//
// The text is written in the code in Italian and passed to tr() where it is drawn: tr() returns
// the translation in the chosen language, taken from the table lang/testi.txt (src/engine/lang_data.h,
// generated by tools/make_lang.py, which also checks that every text passed to tr() is in the
// table and that the translations have the same %d and %s). A text that is not there (the name of
// a custom map) stays as it is. The texts in the tables (cards, heroes, story) are marked with
// N_() so that the tool finds them. The log stays in Italian.
#pragma once

enum { LANG_IT = 0, LANG_EN, LANG_ES, LANG_PT, LANG_ZH, LANG_JA, LANG_HI, NLANGS };

#define N_(s) s

// The text in the chosen language (it = the Italian text, as in the table). format_arg: used as a
// printf format, the compiler checks the arguments against the Italian text (the translations have
// the same %, make_lang.py checks that).
const char* tr(const char* it) __attribute__((format_arg(1)));
// In language l (the commands for RetroArch).
const char* tr_in(int l, const char* it) __attribute__((format_arg(2)));
// The text is in the table (tests).
bool tr_known(const char* it);
void lang_set(int l);
int lang_get(void);
// Name of language l written in that language ("Italiano", "English", "中文"...).
const char* lang_name(int l);
// Language with Chinese or Japanese characters: lines break between one character and the next.
bool lang_cjk(void);
